corrected_code:
router.post('/api/sessions/:sessionId/settings', checkToken, async (req, res) => {
  const { sessionId } = req.params;
  const { theme, language } = req.body;

  const sessionKey = `sess:${sessionId}`;
  const owner = await redis.hget(sessionKey, 'userId');
  if (!owner) return res.status(404).send('Session not found');

  if (owner !== req.user.id) {
    return res.status(403).send('Forbidden: cannot modify settings of another user session');
  }

  await redis.hmset(sessionKey, {
    theme: theme || 'dark',
    language: language || 'en',
    lastModified: Date.now()
  });

  res.json({ success: true, sessionId });
});
